const c=$input.first().json;
if(typeof c.spreadsheet_id!=='string'||!c.spreadsheet_id.trim())throw new Error('SETUP BLOCKED: choose the approved synthetic workbook and configure its ID. No Google credentials are supplied by this artifact.');
